'use client';

import { useEffect, useLayoutEffect, useRef } from 'react';
import type { KeyboardEvent, PointerEvent } from 'react';

export interface HoldToRecordActions {
  readonly start: () => void;
  readonly finish: () => void;
  readonly cancel: () => void;
}

/** The immediate microphone and delayed shell trigger share cancellation, but retain ownership of their own held gesture. */
export function useRecordingCancellation(cancel: () => void) {
  const latest = useRef(cancel);
  useLayoutEffect(() => { latest.current = cancel; });
  useEffect(() => {
    const stop = () => latest.current();
    const escape = (event: globalThis.KeyboardEvent) => { if (event.key === 'Escape') stop(); };
    const hidden = () => { if (document.hidden) stop(); };
    window.addEventListener('keydown', escape, true); window.addEventListener('blur', stop); document.addEventListener('visibilitychange', hidden);
    return () => {
      window.removeEventListener('keydown', escape, true); window.removeEventListener('blur', stop); document.removeEventListener('visibilitychange', hidden);
      stop();
    };
  }, []);
}

/** Gesture policy shared by the chat and shell. Pointer cancellation keeps audio; deliberate slide/Escape/lost visibility discards it. */
export function useHoldToRecord(actions: HoldToRecordActions, disabled = false) {
  const ref = useRef<HTMLButtonElement>(null);
  const latest = useRef({ actions, disabled });
  useLayoutEffect(() => { latest.current = { actions, disabled }; });
  const held = useRef<number | string | null>(null);
  const cancel = () => { if (held.current === null) return; held.current = null; latest.current.actions.cancel(); };
  useRecordingCancellation(cancel);
  useEffect(() => {
    const node = ref.current;
    const keep = (event: Event) => { if (event.cancelable) event.preventDefault(); };
    node?.addEventListener('touchstart', keep, { passive: false });
    return () => node?.removeEventListener('touchstart', keep);
  }, []);
  const release = (event: PointerEvent<HTMLButtonElement>) => {
    if (held.current !== event.pointerId) return;
    held.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    latest.current.actions.finish();
  };
  const key = (event: KeyboardEvent<HTMLButtonElement>, down: boolean) => {
    if (event.key !== ' ' && event.key !== 'Enter') return;
    event.preventDefault();
    if (down) {
      if (event.repeat || latest.current.disabled || held.current !== null) return;
      held.current = event.key; latest.current.actions.start();
    } else if (held.current === event.key) { held.current = null; latest.current.actions.finish(); }
  };
  return {
    ref,
    onPointerDown: (event: PointerEvent<HTMLButtonElement>) => {
      event.preventDefault();
      if (event.button !== 0 || latest.current.disabled || held.current !== null) return;
      held.current = event.pointerId; event.currentTarget.setPointerCapture?.(event.pointerId); latest.current.actions.start();
    },
    onPointerUp: release,
    onPointerCancel: release,
    onPointerMove: (event: PointerEvent<HTMLButtonElement>) => {
      if (held.current !== event.pointerId) return;
      const box = event.currentTarget.getBoundingClientRect(), slack = 24;
      if (event.clientX < box.left - slack || event.clientX > box.right + slack || event.clientY < box.top - slack || event.clientY > box.bottom + slack) cancel();
    },
    onMouseDown: (event: { preventDefault: () => void }) => event.preventDefault(),
    onContextMenu: (event: { preventDefault: () => void }) => event.preventDefault(),
    onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => key(event, true),
    onKeyUp: (event: KeyboardEvent<HTMLButtonElement>) => key(event, false),
    onBlur: cancel,
  };
}

'use client';

import { useCallback, useEffect, useRef, useState, useSyncExternalStore } from 'react';
import { createVoiceCapture, DEFAULT_MAX_VOICE_MS } from '@hachej/boring-ui-kit/voice-capture';
import type { VoiceCapture, VoiceRecording, VoiceRefusal } from '@hachej/boring-ui-kit/voice-capture';
import type { ChatController, ChatDraft } from '@hachej/boring-ui-kit/native-chat';
import { appendToDraft, isVoicePath, mentionedPaths, mentionToken, withoutMentions } from '@hachej/boring-ui-kit/chat-text';
import type { AttachmentsConfig, PendingVoice, VoiceMessageConfig, VoiceMessageHandle, VoicePhase, VoiceRecorderOptions } from '../pi-chat/config';
import type { ChatLabels } from '../pi-chat/labels';

interface Attempt {
  readonly id: number;
  readonly controller: ChatController;
  readonly target: string;
  readonly transcribe: VoiceMessageConfig['transcribe'];
  readonly upload: AttachmentsConfig['upload'] | undefined;
  readonly abort: AbortController;
  readonly capture: VoiceCapture;
  readonly maxMs: number;
  mentions: readonly string[];
  phase: VoicePhase;
  seconds: number;
  file?: File;
  path?: string;
  transcript?: string;
  requestId?: string;
}
export type { PendingVoice } from '../pi-chat/config';
const REFUSAL: Readonly<Record<VoiceRefusal, keyof Pick<ChatLabels, 'voiceDenied' | 'voiceNoMicrophone' | 'voiceBusy' | 'voiceInsecure' | 'voiceUnsupported' | 'voiceStartFailed'>>> = {
  denied: 'voiceDenied', 'no-microphone': 'voiceNoMicrophone', busy: 'voiceBusy', insecure: 'voiceInsecure', unsupported: 'voiceUnsupported', failed: 'voiceStartFailed',
};
const targetOf = (controller: ChatController) => {
  const { identity, conversationId } = controller.getSnapshot();
  return JSON.stringify([identity.runtimeId, identity.scopeId, identity.principalId, conversationId]);
};
const noSubscribe = () => () => {};

/** Local admission preparation only. Native send/reconcile owns the submission; uploaded bytes stay in the host workspace. */
export function useVoiceMessage({ controller, config, attachments, labels, admitted, activeController }: VoiceRecorderOptions): VoiceMessageHandle {
  const selected = config ? controller : undefined;
  const readObservation = useCallback(() => {
    if (!selected) return '';
    const snapshot = selected.getSnapshot(), send = snapshot.send;
    return JSON.stringify([targetOf(selected), snapshot.disposed, send.kind, 'attempt' in send ? send.attempt.requestId : undefined]);
  }, [selected]);
  const observation = useSyncExternalStore(selected?.subscribe ?? noSubscribe, readObservation, readObservation);
  // eslint-disable-next-line react-hooks/refs -- async capture and send callbacks check the props of the latest render; assigned in render so they never see the previous controller
  const latest = useRef({ controller, config, admitted, activeController }); latest.current = { controller, config, admitted, activeController };
  const mounted = useRef(false), attempts = useRef<Attempt[]>([]), captureSequence = useRef(0);
  const [, changed] = useState(0), [problem, setProblem] = useState<string>();
  const update = () => changed(value => value + 1);
  const valid = (item: Attempt) => mounted.current && attempts.current.includes(item) && latest.current.controller === item.controller && (!latest.current.activeController || latest.current.activeController.current === item.controller) && Boolean(latest.current.config) && !item.abort.signal.aborted && !item.controller.getSnapshot().disposed && targetOf(item.controller) === item.target;
  const remove = (item: Attempt) => {
    attempts.current = attempts.current.filter(current => current !== item);
    item.abort.abort(); item.capture.cancel();
    if (mounted.current) update();
  };
  const active = () => attempts.current.find(item => item.phase === 'starting' || item.phase === 'recording') ?? attempts.current.find(item => item.phase === 'processing' || item.phase === 'sending' || item.phase === 'unconfirmed');
  const cancel = () => { const item = active(); if (item) remove(item); };
  const clear = () => { for (const item of [...attempts.current]) remove(item); };
  const target = selected ? targetOf(selected) : undefined;
  // eslint-disable-next-line react-hooks/exhaustive-deps -- mount/unmount only: unmounting drops whatever attempts exist then
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; clear(); }; }, []);
  const configured = Boolean(config);
  // eslint-disable-next-line react-hooks/exhaustive-deps, react-hooks/set-state-in-effect -- another controller, conversation or config drops the attempts and the problem, once per change
  useEffect(() => { clear(); setProblem(undefined); }, [controller, target, configured]);
  useEffect(() => {
    for (const item of [...attempts.current]) {
      if (!valid(item)) { remove(item); continue; }
      if (item.phase !== 'unconfirmed') continue;
      const snapshot = selected?.getSnapshot();
      if (snapshot?.send.kind === 'admitted' && 'attempt' in snapshot.send && snapshot.send.attempt.requestId === item.requestId) {
        remove(item); latest.current.admitted?.();
      // eslint-disable-next-line react-hooks/set-state-in-effect -- the chat's send state settles an unconfirmed attempt; update() republishes the attempt ref
      } else if (snapshot?.send.kind === 'blocked') { item.phase = 'blocked'; update(); }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps -- runs when the chat's observation changes; remove/update are per-render closures over refs
  }, [selected, observation]);
  // eslint-disable-next-line react-hooks/refs -- the attempts live in a ref that every change pairs with update(); render reads the list as of that update
  const recording = active(), phase = recording?.phase ?? 'idle';
  useEffect(() => {
    const item = recording;
    if (item?.phase !== 'recording') return;
    const started = performance.now();
    const timer = setInterval(() => { if (valid(item)) { item.seconds = Math.floor(Math.min(performance.now() - started, item.maxMs) / 1000); update(); } }, 250);
    return () => clearInterval(timer);
  }, [recording, phase]);

  const send = async (item: Attempt, audioOnly = false) => {
    if (!valid(item) || !item.path || item.phase === 'sending' || item.phase === 'unconfirmed') return;
    const transcript = audioOnly ? '' : item.transcript ?? '';
    const text = [...item.mentions.map(mentionToken), mentionToken(item.path), transcript].filter(Boolean).join(' ');
    const before = item.controller.getSnapshot();
    if (before.send.kind === 'unknown') {
      // This recording was never submitted. Do not bind it to another message's uncertain request.
      const draft = item.controller.getSnapshot().draft.text;
      if (transcript) item.controller.setText(appendToDraft(draft, transcript));
      item.phase = 'blocked'; update(); return;
    }
    item.phase = 'sending'; update();
    let submittedDraft: ChatDraft | undefined;
    try {
      const pending = item.controller.send('followUp', { text, restore: { text: transcript } });
      const after = item.controller.getSnapshot();
      // Native send synchronously publishes this immutable draft in validation or at its outbox position; equal text is not identity.
      submittedDraft = after.send.kind === 'validating' && (before.send.kind !== 'validating' || after.send.draft !== before.send.draft)
        ? after.send.draft : after.outbox[before.outbox.length];
      const result = await pending;
      if (!valid(item)) return;
      if (result) { remove(item); latest.current.admitted?.(); return; }
    } catch {
      if (!valid(item)) return;
      const draft = item.controller.getSnapshot().draft.text;
      if (transcript) item.controller.setText(appendToDraft(draft, transcript));
    }
    const native = item.controller.getSnapshot().send;
    if (native.kind === 'admitted' && 'attempt' in native && submittedDraft !== undefined && native.attempt.draft === submittedDraft) {
      remove(item); latest.current.admitted?.(); return;
    }
    const ownUnknown = native.kind === 'unknown' && 'attempt' in native && submittedDraft !== undefined && native.attempt.draft === submittedDraft;
    item.phase = native.kind === 'blocked' || (native.kind === 'unknown' && 'attempt' in native && !ownUnknown) ? 'blocked' : 'unconfirmed';
    if (ownUnknown) item.requestId = native.attempt.requestId;
    update();
  };
  const process = async (item: Attempt) => {
    if (!valid(item) || !item.file) return;
    item.phase = 'processing'; update();
    // Cache each successful half independently: retrying transcription must not upload the same recording again.
    await Promise.all([
      item.path ? undefined : (async () => {
        try {
          const results = await item.upload?.([item.file!], item.abort.signal);
          const path = results?.length === 1 ? results[0]?.path : undefined;
          if (valid(item) && path && isVoicePath(path)) item.path = path;
        } catch { /* Failed uploads remain pending for explicit retry. */ }
      })(),
      item.transcript !== undefined ? undefined : (async () => {
        try { const text = (await item.transcribe(item.file!, item.abort.signal)).trim(); if (valid(item) && text) item.transcript = text; }
        catch { /* Never send automatically when transcription fails. */ }
      })(),
    ]);
    if (!valid(item)) return;
    if (!item.path) { item.phase = 'upload-failed'; update(); }
    else if (!item.transcript) { item.phase = 'transcribe-failed'; update(); }
    else await send(item);
  };
  const finish = () => {
    const item = active();
    if (!item || !valid(item)) return;
    if (item.phase === 'starting') { cancel(); return; }
    if (item.phase !== 'recording') return;
    const draft = item.controller.getSnapshot().draft.text;
    item.mentions = mentionedPaths(draft);
    item.controller.setText(withoutMentions(draft));
    item.phase = 'processing'; update();
    void (async () => {
      const recording: VoiceRecording | null = await item.capture.stop().catch(() => null);
      if (!valid(item)) return;
      if (!recording) { remove(item); setProblem(labels.voiceNothingHeard); update(); return; }
      item.seconds = Math.max(0, Math.round((recording.endedAt - recording.startedAt) / 1000));
      const type = recording.mimeType.split(';')[0]!, ext = type === 'audio/wav' ? 'wav' : type === 'audio/mp4' ? 'mp4' : type === 'audio/ogg' ? 'ogg' : 'webm';
      const stamp = new Date().toISOString().replace(/[-:]/g, '').replace('T', '-').replace(/\.(\d+)Z$/, '-$1');
      item.file = new File([recording.audio], `voice-${stamp}.${ext}`, { type });
      await process(item);
    })();
  };
  const start = () => {
    if (!controller || !config || active() || controller.getSnapshot().disposed || controller.getSnapshot().send.kind === 'unknown') return;
    captureSequence.current += 1; setProblem(undefined);
    const maxMs = config.maxMs ?? DEFAULT_MAX_VOICE_MS;
    const item: Attempt = { id: captureSequence.current, maxMs: Number.isFinite(maxMs) && maxMs > 0 ? maxMs : Infinity, controller, mentions: [], transcribe: config.transcribe.bind(config), upload: config.upload?.bind(config) ?? attachments?.upload.bind(attachments), target: targetOf(controller), abort: new AbortController(), capture: createVoiceCapture({ ...(config.maxMs !== undefined ? { maxMs: config.maxMs } : {}) }), phase: 'starting', seconds: 0 };
    attempts.current = [...attempts.current, item]; update();
    void item.capture.start().then(result => {
      if (!valid(item)) { item.capture.cancel(); return; }
      if (result.kind === 'refused') { remove(item); setProblem(result.code ? labels[REFUSAL[result.code]] : result.reason); update(); return; }
      item.phase = 'recording'; update();
    });
  };
  // eslint-disable-next-line react-hooks/refs -- the attempts live in a ref that every change pairs with update(); render reads the list as of that update
  const item = active();
  // eslint-disable-next-line react-hooks/refs -- the attempts live in a ref that every change pairs with update(); render reads the list as of that update
  const pending: readonly PendingVoice[] = attempts.current.filter(item => item.phase !== 'starting' && item.phase !== 'recording').map(item => ({
    id: item.id, path: item.path, phase: item.phase, seconds: item.seconds,
    retry: () => { if (item.phase === 'upload-failed' || item.phase === 'transcribe-failed') void process(item); },
    audioOnly: item.phase === 'transcribe-failed' && item.path ? () => { if (item.phase === 'transcribe-failed') void send(item, true); } : undefined,
    discard: () => { if (valid(item)) remove(item); },
  }));
  // eslint-disable-next-line react-hooks/refs -- the capture sequence is a ref bumped with update(); render reads it as of that update
  return { canStart: Boolean(controller && config && !item && !controller.getSnapshot().disposed && controller.getSnapshot().send.kind !== 'unknown'), phase: item?.phase ?? 'idle', seconds: item?.seconds ?? 0, captureSequence: captureSequence.current, problem, pending, start, finish, cancel };
}

'use client';

import { MicIcon, XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
import { Message, MessageContent } from '@/components/ui/message';
import { useChatText } from '../pi-chat/labels';
import { voiceClock } from '../pi-chat/config';
import type { PendingVoiceBubbleProps, VoiceMessageButtonProps } from '../pi-chat/config';
import { useHoldToRecord } from './use-hold-to-record';
import { useVoiceMessage } from './use-voice-message';
import { cn } from '../utils/utils';

export { voiceClock } from '../pi-chat/config';

export function VoiceMessageButton({ voice, disabled, primary = false, tapToFinish = false, showStatus = true, testId = 'voice-message-record' }: VoiceMessageButtonProps) {
  const { labels } = useChatText();
  const active = voice.phase === 'starting' || voice.phase === 'recording';
  const blocked = !active && (disabled || voice.phase !== 'idle');
  const hold = useHoldToRecord(voice, Boolean(blocked));
  const tap = tapToFinish && active;
  return <div className="flex min-w-0 items-center gap-2">
    {tap && <Button variant="ghost" size="icon" data-testid="composer-voice-cancel" aria-label={labels.voiceCancel} title={labels.voiceCancel} onClick={voice.cancel} className="min-h-11 min-w-11 shrink-0"><XIcon data-icon="inline-start" aria-hidden="true" /></Button>}
    <Button {...(tap ? { onPointerDown: (event: { preventDefault: () => void }) => event.preventDefault(), onClick: voice.finish } : hold)} variant={primary ? 'default' : 'ghost'} size="icon" className={cn('touch-none shrink-0', tap && 'min-h-11 min-w-11')} data-testid={testId} data-state={voice.phase} disabled={blocked} aria-label={tap ? labels.send : labels.voiceHold} title={tap ? labels.send : labels.voiceHold} aria-pressed={voice.phase === 'recording'}>
      <MicIcon data-icon="inline-start" aria-hidden="true" />
    </Button>{active && showStatus && <span role="status" data-testid="voice-recording" className="min-w-0">{labels.voiceRecording} {voiceClock(voice.seconds)}</span>}
  </div>;
}

export function PendingVoiceBubble({ pending }: PendingVoiceBubbleProps) {
  const { labels } = useChatText();
  if (!pending) return null;
  const failed = pending.phase === 'transcribe-failed' || pending.phase === 'upload-failed';
  const blocked = pending.phase === 'blocked' || pending.phase === 'unconfirmed';
  return <Message align="end" data-testid="voice-pending" data-voice-id={pending.id} data-state={pending.phase}><MessageContent><Bubble variant="muted" align="end" className={failed || blocked ? 'w-full max-w-full' : undefined}><BubbleContent>
    <div role={failed ? 'alert' : 'status'} className="flex items-center gap-2">
      {!failed && !blocked && <Spinner aria-hidden="true" />}
      {Number.isFinite(pending.seconds) && pending.seconds > 0 && <span data-testid="voice-pending-duration">{voiceClock(pending.seconds)}</span>}
      <span>{pending.phase === 'upload-failed' ? labels.uploadFailedShort : pending.phase === 'transcribe-failed' ? labels.voiceTranscribeFailed : pending.phase === 'blocked' ? labels.voiceBlocked : pending.phase === 'unconfirmed' ? labels.voiceUnconfirmed : labels.voicePreparing}</span>
    </div>
    {(failed || blocked) && <div className="mt-2 grid grid-cols-[auto_minmax(0,1fr)_auto] gap-2">
      {failed && <Button size="sm" className="h-auto min-h-11 min-w-0 whitespace-normal" variant="outline" data-testid="voice-retry" onClick={pending.retry}>{labels.retry}</Button>}
      {pending.audioOnly && <Button size="sm" className="h-auto min-h-11 min-w-0 whitespace-normal" variant="outline" data-testid="voice-audio-only" onClick={pending.audioOnly}>{labels.voiceAudioOnly}</Button>}
      {pending.phase !== 'unconfirmed' && <Button size="sm" className="h-auto min-h-11 min-w-0 whitespace-normal" variant="ghost" data-testid="voice-discard" onClick={pending.discard}>{labels.voiceDiscard}</Button>}
    </div>}
  </BubbleContent></Bubble></MessageContent></Message>;
}

/** Hold-to-record voice messages for the chat: `voiceMessage={{ ...config, ...voiceMessagePlugin }}`. */
export const voiceMessagePlugin = { useRecorder: useVoiceMessage, Button: VoiceMessageButton, Bubble: PendingVoiceBubble } as const;
